"use client"

import * as React from "react"

import {
  mergeCommands,
  rankByQuery,
  rankRecentFirst,
  type MatchRange,
  type RankedCommand,
} from "../lib/df-command"
import { useControllableState } from "../hooks"
import { useDfStrings } from "../lib/df-intl"
import { cn } from "../lib/utils"
import { Dialog, DialogContent } from "./df-dialog"
import { hasKbdShortcut, Kbd } from "./df-kbd"
import { SearchInput } from "./df-search-input"
import { Spinner } from "./df-spinner"

const ASYNC_DEBOUNCE_MS = 160
const PAGE_STEP = 8

export type CommandItem = {
  id: string
  label: string
  section?: string
  keywords?: string[]
  /**
   * Ranking band for query results. Lower tiers sort before higher tiers;
   * fuzzy score breaks ties within the same tier. Defaults to 0.
   */
  rankTier?: number
  glyph?: React.ReactNode
  shortcut?: string
  disabled?: boolean
  run: () => void
}

export type CommandSource = (query: string) => Promise<CommandItem[]>

export type CommandPaletteProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  commands: CommandItem[]
  source?: CommandSource
  recentIds?: string[]
  onRun?: (command: CommandItem) => void
  placeholder?: string
  background?: string
  emptyContent?: React.ReactNode
  footer?: React.ReactNode
  className?: string
}

function highlightLabel(label: string, ranges: MatchRange[]): React.ReactNode {
  if (ranges.length === 0) return label
  const nodes: React.ReactNode[] = []
  let cursor = 0
  ranges.forEach((range, index) => {
    if (range.start > cursor) {
      nodes.push(label.slice(cursor, range.start))
    }
    nodes.push(
      <mark key={`m-${index}`} data-df="command-palette-mark">
        {label.slice(range.start, range.end)}
      </mark>
    )
    cursor = range.end
  })
  if (cursor < label.length) nodes.push(label.slice(cursor))
  return nodes
}

function groupRanked(
  ranked: RankedCommand<CommandItem>[],
  defaultSection: string
): Array<{ section: string; items: RankedCommand<CommandItem>[] }> {
  const groups: Array<{ section: string; items: RankedCommand<CommandItem>[] }> =
    []
  const indexBySection = new Map<string, number>()

  for (const entry of ranked) {
    const section = entry.command.section?.trim() || defaultSection
    const existing = indexBySection.get(section)
    if (existing == null) {
      indexBySection.set(section, groups.length)
      groups.push({ section, items: [entry] })
      continue
    }
    groups[existing]!.items.push(entry)
  }

  return groups
}

function CommandPalette({
  open,
  defaultOpen = false,
  onOpenChange,
  commands,
  source,
  recentIds = [],
  onRun,
  placeholder: placeholderProp,
  background,
  emptyContent,
  footer,
  className,
}: CommandPaletteProps) {
  const s = useDfStrings()
  const placeholder = placeholderProp ?? s.commandPalettePlaceholder
  const [isOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const [query, setQuery] = React.useState("")
  const [asyncCommands, setAsyncCommands] = React.useState<CommandItem[]>([])
  const [loading, setLoading] = React.useState(false)
  const [activeId, setActiveId] = React.useState<string | null>(null)
  const [activeQueryKey, setActiveQueryKey] = React.useState("")
  const listId = React.useId()
  const requestIdRef = React.useRef(0)

  const resetSession = React.useCallback(() => {
    setQuery("")
    setAsyncCommands([])
    setLoading(false)
    setActiveId(null)
    setActiveQueryKey("")
  }, [])

  const handleOpenChange = React.useCallback(
    (next: boolean) => {
      setOpen(next)
      if (!next) resetSession()
    },
    [resetSession, setOpen]
  )

  const merged = React.useMemo(
    () => mergeCommands(commands, asyncCommands),
    [asyncCommands, commands]
  )

  const ranked = React.useMemo(() => {
    const trimmed = query.trim()
    if (!trimmed) return rankRecentFirst(merged, recentIds)
    return rankByQuery(merged, trimmed)
  }, [merged, query, recentIds])

  const groups = React.useMemo(
    () => groupRanked(ranked, s.commandPaletteCommands),
    [ranked, s.commandPaletteCommands]
  )
  const flatIds = React.useMemo(
    () =>
      ranked
        .filter((entry) => !entry.command.disabled)
        .map((entry) => entry.command.id),
    [ranked]
  )

  const queryKey = `${isOpen}:${query}`
  if (isOpen && queryKey !== activeQueryKey) {
    setActiveQueryKey(queryKey)
    const nextActive =
      activeId != null && flatIds.includes(activeId)
        ? activeId
        : (flatIds[0] ?? null)
    if (nextActive !== activeId) setActiveId(nextActive)
  }

  React.useEffect(() => {
    if (!isOpen || !source) return

    const requestId = ++requestIdRef.current
    const timer = window.setTimeout(() => {
      setLoading(true)
      void source(query)
        .then((next) => {
          if (requestIdRef.current !== requestId) return
          setAsyncCommands(next)
          setLoading(false)
        })
        .catch(() => {
          if (requestIdRef.current !== requestId) return
          setAsyncCommands([])
          setLoading(false)
        })
    }, ASYNC_DEBOUNCE_MS)

    return () => {
      window.clearTimeout(timer)
    }
  }, [isOpen, query, source])

  const optionDomId = React.useCallback(
    (id: string) =>
      `${listId}-opt-${id.replace(/[^a-zA-Z0-9_-]/g, "-")}`,
    [listId]
  )

  const moveActive = React.useCallback(
    (delta: number) => {
      if (flatIds.length === 0) return
      const current = activeId == null ? -1 : flatIds.indexOf(activeId)
      const base = current === -1 ? (delta > 0 ? -1 : 0) : current
      const next =
        flatIds[(base + delta + flatIds.length * 10) % flatIds.length] ?? null
      setActiveId(next)
      if (next != null) {
        document
          .getElementById(optionDomId(next))
          ?.scrollIntoView({ block: "nearest" })
      }
    },
    [activeId, flatIds, optionDomId]
  )

  const runActive = React.useCallback(() => {
    if (activeId == null) return
    const entry = ranked.find((item) => item.command.id === activeId)
    if (!entry || entry.command.disabled) return
    handleOpenChange(false)
    onRun?.(entry.command)
    entry.command.run()
  }, [activeId, handleOpenChange, onRun, ranked])

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown") {
      event.preventDefault()
      moveActive(1)
      return
    }
    if (event.key === "ArrowUp") {
      event.preventDefault()
      moveActive(-1)
      return
    }
    if (event.key === "PageDown") {
      event.preventDefault()
      moveActive(PAGE_STEP)
      return
    }
    if (event.key === "PageUp") {
      event.preventDefault()
      moveActive(-PAGE_STEP)
      return
    }
    if (event.key === "Enter") {
      event.preventDefault()
      runActive()
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent
        className={cn(className)}
        aria-label={s.commandPaletteAriaLabel}
      >
        <div data-df="command-palette">
          <div data-df="command-palette-search">
            <SearchInput
              size="md"
              clearable
              placeholder={placeholder}
              background={background}
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onClear={() => setQuery("")}
              onKeyDown={handleKeyDown}
              role="combobox"
              aria-expanded={isOpen}
              aria-controls={listId}
              aria-autocomplete="list"
              aria-activedescendant={
                activeId != null ? optionDomId(activeId) : undefined
              }
            />
          </div>

          <div data-df="command-palette-body">
            {loading ? (
              <div data-df="command-palette-loading" role="status">
                <Spinner size="sm" aria-hidden />
                <span>{s.commandPaletteSearching}</span>
              </div>
            ) : null}

            {!loading && ranked.length === 0 ? (
              <div data-df="command-palette-empty" role="status">
                {emptyContent ?? s.commandPaletteEmpty}
              </div>
            ) : null}

            {ranked.length > 0 ? (
              <div
                id={listId}
                role="listbox"
                data-df="command-palette-list"
                aria-label={s.commandPaletteCommands}
              >
                {groups.map((group) => (
                  <div
                    key={group.section}
                    data-df="command-palette-section"
                    role="group"
                    aria-label={group.section}
                  >
                    <div data-df="command-palette-section-label">
                      {group.section}
                    </div>
                    {group.items.map((entry) => {
                      const active = entry.command.id === activeId
                      return (
                        <div
                          key={entry.command.id}
                          id={optionDomId(entry.command.id)}
                          role="option"
                          aria-selected={active}
                          aria-disabled={entry.command.disabled || undefined}
                          data-df="command-palette-item"
                          data-active={active ? "" : undefined}
                          data-disabled={
                            entry.command.disabled ? "" : undefined
                          }
                          onMouseEnter={() => {
                            if (!entry.command.disabled) {
                              setActiveId(entry.command.id)
                            }
                          }}
                          onClick={() => {
                            if (entry.command.disabled) return
                            handleOpenChange(false)
                            onRun?.(entry.command)
                            entry.command.run()
                          }}
                        >
                          {entry.command.glyph != null ? (
                            <span data-df="command-palette-glyph" aria-hidden>
                              {entry.command.glyph}
                            </span>
                          ) : null}
                          <span data-df="command-palette-label">
                            {highlightLabel(
                              entry.command.label,
                              entry.ranges
                            )}
                          </span>
                          {hasKbdShortcut(entry.command.shortcut) ? (
                            <span data-df="command-palette-shortcut">
                              <Kbd size="sm">{entry.command.shortcut}</Kbd>
                            </span>
                          ) : null}
                        </div>
                      )
                    })}
                  </div>
                ))}
              </div>
            ) : null}
          </div>

          <div data-df="command-palette-footer">
            {footer ?? (
              <>
                <span>
                  <Kbd size="sm">↑</Kbd>
                  <Kbd size="sm">↓</Kbd> {s.commandPaletteNavigate}
                </span>
                <span>
                  <Kbd size="sm">↵</Kbd> {s.commandPaletteRun}
                </span>
                <span>
                  <Kbd size="sm">Esc</Kbd> {s.commandPaletteClose}
                </span>
              </>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

export { CommandPalette }

export {
  mergeCommands,
  rankByQuery,
  rankRecentFirst,
  type RankableCommand,
  type RankedCommand,
} from "./rank"
export {
  compareFuzzyScores,
  scoreFuzzy,
  type FuzzyScore,
  type MatchRange,
} from "./score"

import { compareFuzzyScores, scoreFuzzy, type MatchRange } from "./score"

export type RankableCommand = {
  id: string
  label: string
  section?: string
  keywords?: string[]
  /** Lower tiers sort before higher tiers. Defaults to 0. */
  rankTier?: number
}

export type RankedCommand<T extends RankableCommand> = {
  command: T
  score: number
  ranges: MatchRange[]
}

/**
 * Rank commands for an empty query: recent ids first (in host order),
 * then remaining commands in their original order.
 */
export function rankRecentFirst<T extends RankableCommand>(
  commands: T[],
  recentIds: string[]
): RankedCommand<T>[] {
  const byId = new Map(commands.map((command) => [command.id, command]))
  const seen = new Set<string>()
  const ranked: RankedCommand<T>[] = []

  for (const id of recentIds) {
    const command = byId.get(id)
    if (!command || seen.has(id)) continue
    seen.add(id)
    ranked.push({ command, score: 0, ranges: [] })
  }

  for (const command of commands) {
    if (seen.has(command.id)) continue
    ranked.push({ command, score: 0, ranges: [] })
  }

  return ranked
}

/** Score and sort commands for a non empty query. */
export function rankByQuery<T extends RankableCommand>(
  commands: T[],
  query: string
): RankedCommand<T>[] {
  const ranked: RankedCommand<T>[] = []

  for (const command of commands) {
    const haystack = [command.label, ...(command.keywords ?? [])].join(" ")
    const labelMatch = scoreFuzzy(query, command.label)
    const keywordMatch =
      labelMatch == null ? scoreFuzzy(query, haystack) : null
    const match = labelMatch ?? keywordMatch
    if (match == null) continue
    ranked.push({
      command,
      score: match.score,
      ranges: labelMatch?.ranges ?? [],
    })
  }

  ranked.sort((a, b) => {
    const tierA = a.command.rankTier ?? 0
    const tierB = b.command.rankTier ?? 0
    if (tierA !== tierB) return tierA - tierB
    return compareFuzzyScores(
      { score: a.score, label: a.command.label },
      { score: b.score, label: b.command.label }
    )
  })

  return ranked
}

/** Merge static and async command lists, preferring the first id wins. */
export function mergeCommands<T extends RankableCommand>(
  primary: T[],
  secondary: T[]
): T[] {
  const seen = new Set<string>()
  const merged: T[] = []
  for (const command of [...primary, ...secondary]) {
    if (seen.has(command.id)) continue
    seen.add(command.id)
    merged.push(command)
  }
  return merged
}

export type MatchRange = {
  start: number
  end: number
}

export type FuzzyScore = {
  score: number
  ranges: MatchRange[]
}

const BONUS_EXACT_PREFIX = 24
const BONUS_WORD_START = 12
const BONUS_CONSECUTIVE = 8
const BONUS_BOUNDARY = 4
const PENALTY_GAP = 2
const PENALTY_LEADING = 1

function isWordBoundary(text: string, index: number): boolean {
  if (index <= 0) return true
  const prev = text[index - 1]
  const curr = text[index]
  if (prev == null || curr == null) return false
  if (/[\s\-_/.:]/.test(prev)) return true
  if (prev === prev.toLowerCase() && curr === curr.toUpperCase()) return true
  return false
}

function mergeRanges(indices: number[]): MatchRange[] {
  if (indices.length === 0) return []
  const ranges: MatchRange[] = []
  let start = indices[0]!
  let end = start + 1
  for (let i = 1; i < indices.length; i++) {
    const index = indices[i]!
    if (index === end) {
      end = index + 1
      continue
    }
    ranges.push({ start, end })
    start = index
    end = index + 1
  }
  ranges.push({ start, end })
  return ranges
}

/**
 * Case insensitive subsequence match with bonuses for exact prefixes,
 * word starts, and consecutive runs. Returns null when the query does not match.
 */
export function scoreFuzzy(query: string, text: string): FuzzyScore | null {
  const q = query.trim().toLowerCase()
  if (q.length === 0) {
    return { score: 0, ranges: [] }
  }

  const source = text
  const lower = source.toLowerCase()
  if (q.length > lower.length) return null

  const matched: number[] = []
  let score = 0
  let qIndex = 0
  let consecutive = 0
  let prevMatch = -1

  for (let i = 0; i < lower.length && qIndex < q.length; i++) {
    if (lower[i] !== q[qIndex]) {
      consecutive = 0
      continue
    }

    matched.push(i)
    if (prevMatch === -1) {
      score -= i * PENALTY_LEADING
    } else if (i === prevMatch + 1) {
      consecutive += 1
      score += BONUS_CONSECUTIVE * consecutive
    } else {
      consecutive = 0
      score -= (i - prevMatch - 1) * PENALTY_GAP
    }

    if (isWordBoundary(source, i)) {
      score += BONUS_WORD_START
    } else if (i > 0 && /[0-9]/.test(source[i]!) && /[^0-9]/.test(source[i - 1]!)) {
      score += BONUS_BOUNDARY
    }

    prevMatch = i
    qIndex += 1
  }

  if (qIndex < q.length) return null

  if (lower.startsWith(q)) {
    score += BONUS_EXACT_PREFIX
  }

  score += Math.max(0, 32 - (lower.length - q.length))

  return {
    score,
    ranges: mergeRanges(matched),
  }
}

/** Compare two fuzzy scores descending; stable by label when tied. */
export function compareFuzzyScores(
  a: { score: number; label: string },
  b: { score: number; label: string }
): number {
  if (b.score !== a.score) return b.score - a.score
  return a.label.localeCompare(b.label)
}

/** CSS selector for tabbable controls inside a modal panel. */
export const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "textarea:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(",")

export type FocusTrapKeyAction =
  | "close"
  | "focus-panel"
  | "focus-last"
  | "focus-first"
  | "none"

export type FocusTrapKeyDecision = {
  action: FocusTrapKeyAction
  preventDefault: boolean
}

/**
 * Decide how a keydown should affect a modal focus trap.
 * Escape closes. Tab cycles only when focus is on an edge item.
 */
export function resolveFocusTrapKey(options: {
  key: string
  shiftKey: boolean
  focusableCount: number
  activeIsFirst: boolean
  activeIsLast: boolean
}): FocusTrapKeyDecision {
  if (options.key === "Escape") {
    return { action: "close", preventDefault: true }
  }
  if (options.key !== "Tab") {
    return { action: "none", preventDefault: false }
  }
  if (options.focusableCount === 0) {
    return { action: "focus-panel", preventDefault: true }
  }
  if (options.shiftKey && options.activeIsFirst) {
    return { action: "focus-last", preventDefault: true }
  }
  if (!options.shiftKey && options.activeIsLast) {
    return { action: "focus-first", preventDefault: true }
  }
  return { action: "none", preventDefault: false }
}

/** Prefer the trigger, then the focus captured when the layer opened. */
export function resolveFocusRestoreTarget<T>(
  trigger: T | null | undefined,
  previous: T | null | undefined
): T | null {
  return trigger ?? previous ?? null
}

/** First tabbable control, or the panel itself when the panel has none. */
export function resolveInitialFocus<T>(
  focusables: readonly T[],
  panel: T | null | undefined
): T | null {
  return focusables[0] ?? panel ?? null
}

export type OverflowStyleHost = {
  style: { overflow: string }
}

/** Lock page scroll and return the prior overflow value for restore. */
export function lockBodyScroll(body: OverflowStyleHost): string {
  const previous = body.style.overflow
  body.style.overflow = "hidden"
  return previous
}

/** Restore page scroll from a value returned by lockBodyScroll. */
export function unlockBodyScroll(
  body: OverflowStyleHost,
  previousOverflow: string
): void {
  body.style.overflow = previousOverflow
}

import { useEffect, useRef, type RefObject } from "react"

import {
  FOCUSABLE_SELECTOR,
  lockBodyScroll,
  resolveFocusRestoreTarget,
  resolveFocusTrapKey,
  resolveInitialFocus,
  unlockBodyScroll,
} from "./trap"

type UseFocusTrapOptions = {
  open: boolean
  panelRef: RefObject<HTMLElement | null>
  triggerRef: RefObject<HTMLElement | null>
  onEscape: () => void
}

/**
 * Modal focus lifecycle: capture prior focus, lock scroll, move focus into
 * the panel, trap Tab, close on Escape, and restore focus on close.
 */
export function useFocusTrap({
  open,
  panelRef,
  triggerRef,
  onEscape,
}: UseFocusTrapOptions) {
  const previousFocusRef = useRef<HTMLElement | null>(null)
  const wasOpenRef = useRef(false)
  const onEscapeRef = useRef(onEscape)

  useEffect(() => {
    onEscapeRef.current = onEscape
  }, [onEscape])

  useEffect(() => {
    if (!open) {
      if (wasOpenRef.current) {
        wasOpenRef.current = false
        const restore = resolveFocusRestoreTarget(
          triggerRef.current,
          previousFocusRef.current
        )
        previousFocusRef.current = null
        restore?.focus?.()
      }
      return
    }

    wasOpenRef.current = true
    const active = document.activeElement
    previousFocusRef.current =
      active instanceof HTMLElement ? active : null

    const previousOverflow = lockBodyScroll(document.body)
    const panel = panelRef.current
    const focusables = panel
      ? Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR))
      : []
    const initial = resolveInitialFocus(focusables, panel)
    initial?.focus?.()

    return () => {
      unlockBodyScroll(document.body, previousOverflow)
    }
  }, [open, panelRef, triggerRef])

  useEffect(() => {
    if (!open) return

    const onKeyDown = (event: KeyboardEvent) => {
      const panel = panelRef.current
      const focusables = panel
        ? Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR))
        : []
      const decision = resolveFocusTrapKey({
        key: event.key,
        shiftKey: event.shiftKey,
        focusableCount: focusables.length,
        activeIsFirst: document.activeElement === focusables[0],
        activeIsLast:
          document.activeElement === focusables[focusables.length - 1],
      })

      if (decision.action === "none") return
      if (decision.preventDefault) event.preventDefault()

      if (decision.action === "close") {
        onEscapeRef.current()
        return
      }
      if (decision.action === "focus-panel") {
        panel?.focus()
        return
      }
      if (decision.action === "focus-last") {
        focusables[focusables.length - 1]?.focus()
        return
      }
      if (decision.action === "focus-first") {
        focusables[0]?.focus()
      }
    }

    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [open, panelRef])
}
